class ParentBuild {
    ParentBuild(){ System.out.println(status()); }
    String status(){ return "parent"; }
}
class ChildBuild extends ParentBuild {
    private int ready = 7;
    @Override String status(){ return "child=" + ready; }
}
public class ConstructorOverrideDispatchDemo {
    public static void main(String[] args){ new ChildBuild(); }
}
